:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8a9a;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  padding: 24px;
  border: 4px solid var(--accent);
  box-shadow: 6px 6px 0 #0f0f1a;
}
h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}
.input-row { display: flex; gap: 8px; }
input[type="text"] {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  font-size: 1rem;
  color: var(--text);
  background: #0f0f1a;
  border: 3px solid var(--muted);
  outline: none;
}
input[type="text"]:focus { border-color: var(--accent); }
button {
  padding: 10px 16px;
  font-size: 1rem;
  font-weight: bold;
  color: #0f0f1a;
  background: var(--accent);
  border: 3px solid var(--accent);
  cursor: pointer;
  transition: transform 0.05s, background 0.15s;
}
button:hover { background: #ff6b81; }
button:active { transform: translate(2px, 2px); }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
.counts {
  display: flex;
  gap: 24px;
  margin: 16px 0;
  font-size: 0.95rem;
  color: var(--muted);
}
.counts strong { color: var(--text); }
.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.todo-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  background: #0f0f1a;
  border: 2px solid var(--muted);
}
.todo-list li.done span { text-decoration: line-through; color: var(--muted); }
.todo-list input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}
.todo-list span { flex: 1; word-break: break-word; }
.todo-list .delete {
  padding: 4px 8px;
  font-size: 0.85rem;
  background: transparent;
  color: var(--accent);
  border: 2px solid var(--accent);
}
.todo-list .delete:hover { background: var(--accent); color: #0f0f1a; }
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  .input-row { flex-direction: column; }
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const form = document.getElementById('todo-form');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

let tasks = [];
let nextId = 1;

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.done).length;
}

function renderTask(task) {
  const li = document.createElement('li');
  li.dataset.id = task.id;
  if (task.done) li.classList.add('done');

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = `todo-check-${task.id}`;
  checkbox.checked = task.done;
  checkbox.setAttribute('aria-label', `Mark "${task.text}" as ${task.done ? 'incomplete' : 'complete'}`);
  checkbox.addEventListener('change', () => {
    task.done = checkbox.checked;
    li.classList.toggle('done', task.done);
    checkbox.setAttribute('aria-label', `Mark "${task.text}" as ${task.done ? 'incomplete' : 'complete'}`);
    updateCounts();
  });

  const span = document.createElement('span');
  span.id = `todo-text-${task.id}`;
  span.textContent = task.text;

  const del = document.createElement('button');
  del.type = 'button';
  del.id = `todo-delete-${task.id}`;
  del.className = 'delete';
  del.textContent = 'Delete';
  del.setAttribute('aria-label', `Delete task "${task.text}"`);
  del.addEventListener('click', () => {
    tasks = tasks.filter(t => t.id !== task.id);
    li.remove();
    updateCounts();
  });

  li.append(checkbox, span, del);
  list.appendChild(li);
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, done: false };
  tasks.push(task);
  renderTask(task);
  input.value = '';
  input.focus();
  updateCounts();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  addTask();
});

addBtn.addEventListener('click', (e) => {
  e.preventDefault();
  addTask();
});

updateCounts();
